import React, { useState } from "react";
import axios from "axios";

const Login = () => {

  const [page, setPage] = useState("login"); 
  const [form, setForm] = useState({
    name: "",
    phone: "",
    email: "",
    password: "",
    otp: "",
    newPassword: ""
  });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const registerUser = async () => {
    const res = await axios.post("http://localhost:5000/register", form);
    alert(res.data);
    setPage("login");
  };

  const loginUser = async () => {
    const res = await axios.post("http://localhost:5000/login", {
      email: form.email,
      password: form.password
    });
    alert(res.data);
  };

  const sendOTP = async () => {
    const res = await axios.post("http://localhost:5000/send-otp", {
      phone: form.phone
    });
    alert(res.data);
  };

  const resetPassword = async () => {
    const res = await axios.post("http://localhost:5000/reset-password", {
      phone: form.phone,
      otp: form.otp,
      newPassword: form.newPassword
    });
    alert(res.data);
    setPage("login");
  };

  return (
    <div style={{display:"flex", justifyContent:"center", marginTop:"100px"}}>

      {page === "login" && (
        <div>
          <h2>Login</h2>
          <input name="email" placeholder="Email" onChange={handleChange} /><br/><br/>
          <input name="password" type="password" placeholder="Password" onChange={handleChange} /><br/><br/>
          <button onClick={loginUser}>Login</button><br/><br/>

          <p onClick={() => setPage("register")} style={{cursor:"pointer"}}>
            Don’t have an account? Register
          </p>

          <p onClick={() => setPage("forgot")} style={{cursor:"pointer"}}>
            Forgot Password?
          </p>
        </div>
      )}

      {page === "register" && (
        <div>
          <h2>Register</h2>
          <input name="name" placeholder="Name" onChange={handleChange} /><br/><br/>
          <input name="phone" placeholder="Phone" onChange={handleChange} /><br/><br/>
          <input name="email" placeholder="Email" onChange={handleChange} /><br/><br/>
          <input name="password" type="password" placeholder="Password" onChange={handleChange} /><br/><br/>
          <button onClick={registerUser}>Register</button><br/><br/>

          <p onClick={() => setPage("login")} style={{cursor:"pointer"}}>
            Already have an account? Login
          </p>
        </div>
      )}

      {page === "forgot" && (
        <div>
          <h2>Reset Password</h2>
          <input name="phone" placeholder="Registered Phone" onChange={handleChange} /><br/><br/>
          <button onClick={sendOTP}>Send OTP</button><br/><br/>

          <input name="otp" placeholder="Enter OTP" onChange={handleChange} /><br/><br/>
          <input name="newPassword" type="password" placeholder="New Password" onChange={handleChange} /><br/><br/>
          <button onClick={resetPassword}>Update Password</button><br/><br/>

          <p onClick={() => setPage("login")} style={{cursor:"pointer"}}>
            Back to Login
          </p>
        </div>
      )}

    </div>
  );
};

export default Login;
